import { createStore } from 'zustand/vanilla';
import type { CreateDiagramInput, DiagramEditRun, PromptReference } from '../../../../domain/mapping/agent/diagramEdit';
import type { PromptOperation } from '../../../../domain/mapping/agent/promptTemplates';
import type { DiagramEditClient } from './diagramEditClient';
import { createPromptDraft, insertReferenceWithCursor, serializePromptDraft, type PromptCursor, type PromptDraft } from './promptDraft';

/** The fixed destination: the diagram to revise, or the anchor new diagrams are created beside. */
export interface PromptComposerTarget { operation: PromptOperation; canvasId: string; documentId: string; nodeId: string; label: string }
export interface PromptComposerEntry {
  target: PromptComposerTarget;
  draft: PromptDraft;
  pending: boolean;
  /** The exact request sent; retries resend it unchanged. */
  request?: CreateDiagramInput;
  run?: DiagramEditRun;
  error?: string;
}
/** A reference picked up from the revision list, waiting for a click in a prompt or on a canvas. */
export interface CarriedReference { reference: PromptReference }
export const composerKey = (target: Pick<PromptComposerTarget, 'operation' | 'documentId' | 'nodeId'>) =>
  JSON.stringify([target.operation, target.documentId, target.nodeId]);
export const composerUnsettled = (entry: PromptComposerEntry) => entry.pending || !!entry.request && (!entry.run
  || ['generating', 'applying', 'awaiting-acknowledgement'].includes(entry.run.status));

/** UI lifetime is independent of selection, panels and undo. Only the backend applies revisions. */
export class PromptComposerCoordinator {
  readonly store = createStore<{ entries: Record<string, PromptComposerEntry>; activeKey?: string; carried?: CarriedReference }>(() => ({ entries: {} }));
  private timers = new Map<string, ReturnType<typeof setTimeout>>();
  private polling = new Set<string>();
  private cursors = new Map<string, PromptCursor>();
  private stopped = false;
  constructor(private readonly client: DiagramEditClient, private readonly pollMs = 750) {}
  private entry(key: string) { return this.store.getState().entries[key]; }
  private patch(key: string, patch: Partial<PromptComposerEntry>) {
    if (this.stopped || !this.entry(key)) return;
    this.store.setState(state => ({ entries: { ...state.entries, [key]: { ...state.entries[key], ...patch } } }));
  }
  open(target: PromptComposerTarget) {
    const key = composerKey(target);
    this.store.setState(state => ({ activeKey: key, entries: { ...state.entries,
      [key]: state.entries[key] ?? { target: { ...target }, draft: createPromptDraft(target.operation), pending: false } } }));
    return key;
  }
  show(key: string) { this.store.setState({ activeKey: key }); }
  close() {
    const key = this.store.getState().activeKey;
    this.store.setState({ carried: undefined });
    if (key && !composerUnsettled(this.entry(key))) this.dismiss(key);
    else this.store.setState({ activeKey: undefined });
  }
  dismiss(key: string) {
    const entry = this.entry(key);
    if (!entry || composerUnsettled(entry)) return;
    clearTimeout(this.timers.get(key)); this.timers.delete(key); this.cursors.delete(key);
    this.store.setState(state => {
      const entries = { ...state.entries }; delete entries[key];
      return { entries, activeKey: state.activeKey === key ? undefined : state.activeKey };
    });
  }
  /** Drafts lock while a request is unsettled, so a retry always matches what the user sees. */
  updateDraft(key: string, update: (draft: PromptDraft) => PromptDraft) {
    const entry = this.entry(key);
    if (!entry || composerUnsettled(entry)) return;
    try { this.patch(key, { draft: update(entry.draft), error: undefined }); }
    catch (error) { this.patch(key, { error: error instanceof Error ? error.message : String(error) }); }
  }
  setCursor(key: string, cursor: PromptCursor) { this.cursors.set(key, cursor); }
  /** Inserts into the active composer at its last cursor. Returns false when no composer can take it. */
  insertReference(reference: PromptReference, key = this.store.getState().activeKey) {
    const entry = key && this.entry(key);
    if (!key || !entry || composerUnsettled(entry)) return false;
    let cursor: PromptCursor | undefined;
    this.updateDraft(key, draft => {
      const inserted = insertReferenceWithCursor(draft, reference, this.cursors.get(key));
      cursor = inserted.cursor;
      return inserted.draft;
    });
    if (cursor) this.cursors.set(key, cursor);
    return !!cursor;
  }
  carry(reference?: PromptReference) { this.store.setState({ carried: reference && { reference: structuredClone(reference) } }); }
  private accept(key: string, run: DiagramEditRun) {
    this.patch(key, { run, error: undefined });
    this.schedule(key);
  }
  private schedule(key: string) {
    clearTimeout(this.timers.get(key)); this.timers.delete(key);
    if (this.stopped || !['generating', 'applying'].includes(this.entry(key)?.run?.status ?? '')) return;
    this.timers.set(key, setTimeout(() => { this.timers.delete(key); void this.refresh(key); }, this.pollMs));
  }
  async submit(key: string) {
    const entry = this.entry(key);
    if (!entry || composerUnsettled(entry) || this.stopped) return;
    const { prompt, references } = serializePromptDraft(entry.draft);
    if (!prompt) return;
    this.patch(key, { pending: true, error: undefined, run: undefined, request: undefined });
    try {
      const { target, draft } = entry;
      const capture = await this.client.capture(target.canvasId, target.documentId, target.nodeId);
      if (this.stopped) return;
      const request: CreateDiagramInput = { ...capture, nodeId: target.nodeId, prompt, requestId: crypto.randomUUID(),
        template: structuredClone(draft.template), ...(references.length ? { references } : {}),
        ...(target.operation === 'create-diagram' ? { count: draft.count } : {}) };
      // Retain the exact request before sending: a lost response must never start a second generation.
      this.patch(key, { request });
      this.accept(key, await this.client.start(request, target.operation));
    } catch (error) { this.patch(key, { error: String(error) }); }
    finally { this.patch(key, { pending: false }); }
  }
  async retry(key: string) {
    const entry = this.entry(key);
    if (!entry || entry.pending || this.stopped) return;
    if (!entry.request) return this.submit(key);
    if (entry.run && entry.run.status !== 'awaiting-acknowledgement') return this.refresh(key);
    this.patch(key, { pending: true, error: undefined });
    try { this.accept(key, await this.client.start(entry.request, entry.target.operation)); }
    catch (error) { this.patch(key, { error: String(error) }); }
    finally { this.patch(key, { pending: false }); }
  }
  async refresh(key: string) {
    const run = this.entry(key)?.run;
    if (!run || this.polling.has(key) || this.stopped) return;
    this.polling.add(key);
    try {
      const next = await this.client.status(run.runId);
      // A cancel/retry response may already have moved this run forward while the read was in flight.
      if (this.entry(key)?.run === run) this.accept(key, next);
    } catch (error) { if (this.entry(key)?.run === run) this.patch(key, { error: `Could not refresh progress: ${String(error)}` }); }
    finally {
      this.polling.delete(key);
      if (this.entry(key)?.run !== run && !this.timers.has(key)) this.schedule(key);
    }
  }
  async cancel(key: string) {
    const entry = this.entry(key);
    if (!entry || entry.pending || entry.run?.status !== 'generating' || this.stopped) return;
    this.patch(key, { pending: true });
    try { this.accept(key, await this.client.cancel(entry.run.runId)); }
    catch (error) { this.patch(key, { error: String(error) }); }
    finally { this.patch(key, { pending: false }); }
  }
  dispose() {
    this.stopped = true;
    for (const timer of this.timers.values()) clearTimeout(timer);
    this.timers.clear();
  }
}

import type { PromptReference } from '../../../../domain/mapping/agent/diagramEdit';
import { defaultOptions, defaultTemplateSelection, findPromptTemplate, type PromptOperation, type PromptOptionValue, type PromptTemplateSelection } from '../../../../domain/mapping/agent/promptTemplates';

export type PromptBlock = { kind: 'text'; id: string; text: string } | { kind: 'reference'; id: string; reference: PromptReference };
/**
 * The template is a separate field, so nothing can be inserted before it or delete it.
 * The body alternates text and references and always starts and ends with text (possibly empty).
 */
export interface PromptDraft { template: PromptTemplateSelection; body: readonly PromptBlock[]; count: number }
export interface PromptCursor { blockId: string; offset: number }
export const maxPromptReferences = 20;
export const maxPromptCount = 4;

const textBlock = (text = ''): PromptBlock => ({ kind: 'text', id: crypto.randomUUID(), text });
export function createPromptDraft(operation: PromptOperation): PromptDraft {
  return { template: defaultTemplateSelection(operation), body: [textBlock()], count: 1 };
}

/** Merge adjacent text and keep a text block between references and at both ends. */
function normalize(body: readonly PromptBlock[]): PromptBlock[] {
  const result: PromptBlock[] = [];
  for (const block of body) {
    const last = result.at(-1);
    if (block.kind === 'text' && last?.kind === 'text') result[result.length - 1] = { ...last, text: last.text + block.text };
    else { if (block.kind === 'reference' && last?.kind !== 'text') result.push(textBlock()); result.push(block); }
  }
  if (result.at(-1)?.kind !== 'text') result.push(textBlock());
  if (result[0]?.kind !== 'text') result.unshift(textBlock());
  return result;
}
export const draftReferences = (draft: PromptDraft) => draft.body.flatMap(block => block.kind === 'reference' ? [block.reference] : []);

/** Insert at the cursor, splitting its text; without a cursor (or a stale one) append at the end. */
export function insertReference(draft: PromptDraft, reference: PromptReference, cursor?: PromptCursor): PromptDraft {
  return insertReferenceWithCursor(draft, reference, cursor).draft;
}
/** Also returns the caret just after the new chip, so successive insertions keep their order. */
export function insertReferenceWithCursor(draft: PromptDraft, reference: PromptReference, cursor?: PromptCursor): { draft: PromptDraft; cursor: PromptCursor } {
  if (draftReferences(draft).length >= maxPromptReferences) throw Error(`A prompt can hold at most ${maxPromptReferences} references.`);
  const index = cursor ? draft.body.findIndex(block => block.id === cursor.blockId && block.kind === 'text') : -1;
  const chip: PromptBlock = { kind: 'reference', id: crypto.randomUUID(), reference: structuredClone(reference) };
  let body: PromptBlock[];
  if (index < 0) body = normalize([...draft.body, chip]);
  else {
    const block = draft.body[index] as Extract<PromptBlock, { kind: 'text' }>;
    const offset = Math.max(0, Math.min(block.text.length, cursor!.offset));
    body = normalize([...draft.body.slice(0, index), { ...block, text: block.text.slice(0, offset) },
      chip, textBlock(block.text.slice(offset)), ...draft.body.slice(index + 1)]);
  }
  return { draft: { ...draft, body }, cursor: { blockId: body[body.findIndex(block => block.id === chip.id) + 1].id, offset: 0 } };
}
export function removeBlock(draft: PromptDraft, blockId: string): PromptDraft {
  return { ...draft, body: normalize(draft.body.filter(block => block.id !== blockId || block.kind === 'text')) };
}
export function setBlockText(draft: PromptDraft, blockId: string, text: string): PromptDraft {
  return { ...draft, body: draft.body.map(block => block.id === blockId && block.kind === 'text' ? { ...block, text } : block) };
}
/** Switching templates resets options and edited Markdown: neither carries meaning across templates. */
export function selectTemplate(draft: PromptDraft, templateId: string, version?: number): PromptDraft {
  const definition = findPromptTemplate(templateId, version);
  if (!definition) return draft;
  return { ...draft, template: { id: definition.id, version: definition.version, options: defaultOptions(definition) } };
}
export function setTemplateOption(draft: PromptDraft, key: string, value: PromptOptionValue): PromptDraft {
  return { ...draft, template: { ...draft.template, options: { ...draft.template.options, [key]: value } } };
}
export function setTemplateMarkdown(draft: PromptDraft, markdown: string | undefined): PromptDraft {
  const definition = findPromptTemplate(draft.template.id, draft.template.version);
  const { markdown: _, ...template } = draft.template;
  return { ...draft, template: markdown === undefined || markdown === definition?.markdown ? template : { ...template, markdown } };
}
export function setCount(draft: PromptDraft, count: number): PromptDraft {
  return { ...draft, count: Math.max(1, Math.min(maxPromptCount, Math.round(count))) };
}

export function referenceSummary(reference: PromptReference) {
  return reference.kind === 'diagram' ? reference.label : `${reference.label} · ${reference.nodeIds.length || 'region'}${reference.nodeIds.length === 1 ? ' node' : reference.nodeIds.length ? ' nodes' : ''}`;
}
/** Body text with each reference cited in order as [ref N]; references[N-1] is its pinned target. */
export function serializePromptDraft(draft: PromptDraft): { prompt: string; references: PromptReference[] } {
  const references: PromptReference[] = [];
  const prompt = draft.body.map(block => {
    if (block.kind === 'text') return block.text;
    references.push(structuredClone(block.reference));
    return `[ref ${references.length}]`;
  }).join('').trim();
  return { prompt, references };
}

import type { Diagram } from '../../../../domain/core/diagrams/diagram';
import { promptReferenceSchema, type PromptReference } from '../../../../domain/mapping/agent/diagramEdit';
import type { MappingPocGridRect } from '../../../../domain/mapping/selection/mappingPoc';
import { regionSelectionItem } from '../../../../domain/mapping/selection/selectionState';

/** The first line with words, without box-drawing punctuation: borders make poor labels. */
export function diagramTitle(diagram: Pick<Diagram, 'content' | 'id'>) {
  for (const line of diagram.content.ascii.split('\n')) {
    const words = line.replace(/[^\w.:/ ]+/g, ' ').replace(/\s+/g, ' ').trim();
    if (/[A-Za-z0-9]{2}/.test(words)) return words.slice(0, 80);
  }
  return diagram.id;
}

/** Captured once at insertion: later selection or canvas changes never alter a reference. */
export function diagramReference(diagram: Diagram): PromptReference {
  return { kind: 'diagram', label: diagramTitle(diagram), diagramId: diagram.diagramId, revisionId: diagram.revisionId };
}
export function nodesReference(diagram: Diagram, boxId: string, rect: MappingPocGridRect): PromptReference {
  const item = regionSelectionItem(diagram, boxId, rect, 'capture');
  const lines = diagram.content.ascii.split('\n');
  const endLine = Math.min(rect.endLine, lines.length), startLine = Math.min(rect.startLine, endLine);
  const excerpt = lines.slice(startLine - 1, endLine).map(line => line.slice(rect.startColumn - 1, rect.endColumn).trim()).find(Boolean);
  return { kind: 'nodes', label: (excerpt || diagramTitle(diagram)).slice(0, 80), diagramId: diagram.diagramId, revisionId: diagram.revisionId,
    nodeIds: [...item.region!.selectedIds], range: { startLine, endLine, startColumn: rect.startColumn, endColumn: Math.max(rect.startColumn, rect.endColumn) } };
}

/** Plain text for other apps; HTML carries the structured references so a paste in any composer restores them. */
const attribute = 'data-ide2-prompt-references';
export function promptReferenceClipboard(references: readonly PromptReference[]) {
  const text = references.map(reference => reference.kind === 'diagram' ? `[diagram: ${reference.label}]`
    : `[nodes: ${reference.label} in ${reference.diagramId}]`).join(' ');
  const encoded = btoa(String.fromCharCode(...new TextEncoder().encode(JSON.stringify(references))));
  const escape = (value: string) => value.replace(/[&<>"]/g, char => `&#${char.charCodeAt(0)};`);
  return { text, html: `<span ${attribute}="${encoded}">${escape(text)}</span>` };
}
export async function copyPromptReferences(references: readonly PromptReference[]) {
  const { text, html } = promptReferenceClipboard(references);
  if (typeof ClipboardItem !== 'undefined' && navigator.clipboard?.write) {
    await navigator.clipboard.write([new ClipboardItem({ 'text/plain': new Blob([text], { type: 'text/plain' }), 'text/html': new Blob([html], { type: 'text/html' }) })]);
  } else if (navigator.clipboard?.writeText) await navigator.clipboard.writeText(text);
  else throw Error('Clipboard is unavailable in this browser');
}
/** Returns validated references from pasted HTML, or undefined for ordinary pastes. */
export function pastedPromptReferences(html: string): PromptReference[] | undefined {
  const encoded = html && new DOMParser().parseFromString(html, 'text/html').querySelector(`[${attribute}]`)?.getAttribute(attribute);
  if (!encoded) return undefined;
  try {
    const parsed = JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(encoded), char => char.charCodeAt(0))));
    const references = promptReferenceSchema.array().max(20).safeParse(parsed);
    return references.success ? references.data : undefined;
  } catch { return undefined; }
}

sources.src/features/mapping/prompt-composer/rev:
import { createStore } from 'zustand/vanilla';

const storageKey = 'ide2.diagram-revision-names.v1';
export const maxRevisionNameLength = 80;
function load(): Record<string, string> {
  try {
    const value: unknown = JSON.parse(localStorage.getItem(storageKey) ?? '{}');
    if (!value || typeof value !== 'object') return {};
    return Object.fromEntries(Object.entries(value).filter(([id, name]) => typeof name === 'string' && id.startsWith('diagram-revision-')));
  } catch { return {}; }
}

/** Names live beside revisions, keyed by revision ID: renaming never touches an immutable revision payload. */
export const revisionNames = createStore<{ names: Record<string, string> }>(() => ({ names: typeof localStorage === 'undefined' ? {} : load() }));
export function renameRevision(revisionId: string, name: string) {
  const trimmed = name.trim().slice(0, maxRevisionNameLength);
  revisionNames.setState(state => {
    const names = { ...state.names };
    if (trimmed) names[revisionId] = trimmed; else delete names[revisionId];
    try { localStorage.setItem(storageKey, JSON.stringify(names)); } catch { /* Storage may be disabled; names last for this page. */ }
    return { names };
  });
}

sources.src/features/mapping/window-panel/Window:
import { useEffect, useId, useRef, type CSSProperties, type ReactNode } from 'react';
import type { WindowPanelMode } from './windowPanelState';

const windowPanelModes: readonly WindowPanelMode[] = ['full-single', 'full-split', 'split-single'];
const windowPanelModeLabels: Record<WindowPanelMode, string> = { 'full-single': 'Full screen · single pane', 'full-split': 'Full screen · split panes', 'split-single': 'Beside canvas · single pane' };
import './windowPanel.css';

export interface WindowPanelLayout<Pane extends string> { mode: WindowPanelMode; pane: Pane; focusedPane: Pane; minimized: boolean; ratio: number;
  minimizedWidth: number; expandedWidth?: number; height?: number }
type PaneContent<Pane extends string> = { id: Pane; title: string; content: ReactNode };

/** A workspace overlay with independent pane focus and a compact right-hand view. */
export function WindowPanel<Pane extends string>(props: { title: string; subtitle?: string; notice?: ReactNode; actions?: ReactNode; canvasId: string; state: WindowPanelLayout<Pane>;
  onChange: (patch: Partial<WindowPanelLayout<Pane>>) => void; onClose: () => void; panes: readonly [PaneContent<Pane>] | readonly [PaneContent<Pane>, PaneContent<Pane>]; canvas: ReactNode;
  /** Layouts offered in the header; panels without a canvas pane omit split-single. */ modes?: readonly WindowPanelMode[]; className?: string }) {
  const tabId = useId();
  const body = useRef<HTMLDivElement>(null), drag = useRef(false);
  const panel = useRef<HTMLElement>(null);
  useEffect(() => {
    const element = panel.current!;
    // Trackpad pinch arrives as Ctrl-wheel. Outside the canvas it otherwise
    // magnifies the browser's visual viewport and clips the entire workspace.
    const wheel = (event: WheelEvent) => { if (event.ctrlKey || event.metaKey) event.preventDefault(); };
    element.addEventListener('wheel', wheel, { passive: false });
    return () => element.removeEventListener('wheel', wheel);
  }, []);
  const resize = useRef<{ x: number; y: number; width: number; height: number; areaWidth: number; areaHeight: number; right: number; top: number } | undefined>(undefined);
  const width = props.state.minimized ? props.state.minimizedWidth : props.state.expandedWidth;
  const style: CSSProperties = { ...(width !== undefined ? { left: 'auto', width: `${width * 100}%` } : {}),
    ...(props.state.height !== undefined ? { bottom: 'auto', height: `${props.state.height * 100}%` } : {}) };
  const single = props.panes.length === 1;
  const split = !single && !props.state.minimized && props.state.mode === 'full-split';
  const activePane = props.state.minimized ? props.state.focusedPane : props.state.pane;
  const focus = (pane: Pane) => { if (props.state.focusedPane !== pane) props.onChange({ focusedPane: pane }); };
  const paneEvents = (pane: Pane) => ({ onClickCapture: () => focus(pane), onWheelCapture: () => focus(pane), onPointerDownCapture: () => focus(pane),
    onKeyDownCapture: () => focus(pane), onScrollCapture: (event: React.UIEvent) => { if ((event.target as HTMLElement).dataset.programmaticScroll !== 'true') focus(pane); } });
  return <section ref={panel} style={style} className={`window-panel window-panel-${props.state.mode}${props.state.minimized ? ' window-panel-minimized' : ''}${props.className ? ` ${props.className}` : ''}`} data-window-panel-canvas={props.canvasId} aria-label={props.title}>
    {(['left', 'bottom', 'corner'] as const).map(edge => <div key={edge} className={`window-panel-resize window-panel-resize-${edge}`}
      role="separator" aria-label={edge === 'left' ? 'Resize window width' : edge === 'bottom' ? 'Resize window height' : 'Resize window'}
      aria-orientation={edge === 'bottom' ? 'horizontal' : 'vertical'} tabIndex={0}
      onKeyDown={event => {
        const horizontal = edge !== 'bottom' && ['ArrowLeft', 'ArrowRight'].includes(event.key);
        const vertical = edge !== 'left' && ['ArrowUp', 'ArrowDown'].includes(event.key);
        if (!horizontal && !vertical) return;
        event.preventDefault(); event.stopPropagation();
        const rect = panel.current!.getBoundingClientRect(), area = panel.current!.parentElement!.getBoundingClientRect();
        if (horizontal) props.onChange({ [props.state.minimized ? 'minimizedWidth' : 'expandedWidth']:
          Math.max(.2, Math.min(.95, (rect.width + (event.key === 'ArrowLeft' ? 24 : -24)) / area.width)) });
        else props.onChange({ height: Math.max(.2, Math.min(.95, (rect.height + (event.key === 'ArrowDown' ? 24 : -24)) / area.height)) });
      }}
      onPointerDown={event => {
        if (event.button !== 0) return;
        event.preventDefault(); event.stopPropagation(); event.currentTarget.focus(); event.currentTarget.setPointerCapture(event.pointerId);
        const rect = panel.current!.getBoundingClientRect(), area = panel.current!.parentElement!.getBoundingClientRect();
        resize.current = { x: event.clientX, y: event.clientY, width: rect.width, height: rect.height,
          areaWidth: area.width, areaHeight: area.height, right: rect.right - area.left, top: rect.top - area.top };
      }}
      onPointerMove={event => {
        const start = resize.current; if (!start) return;
        event.preventDefault(); event.stopPropagation();
        props.onChange({ ...(edge !== 'bottom' ? { [props.state.minimized ? 'minimizedWidth' : 'expandedWidth']:
          Math.max(.2, Math.min(.95, (start.right - 8) / start.areaWidth, (start.width + start.x - event.clientX) / start.areaWidth)) } : {}),
          ...(edge !== 'left' ? { height: Math.max(.2, Math.min(.95, (start.areaHeight - start.top - 8) / start.areaHeight,
            (start.height + event.clientY - start.y) / start.areaHeight)) } : {}) });
      }}
      onPointerUp={() => { resize.current = undefined; }} onPointerCancel={() => { resize.current = undefined; }}
      onLostPointerCapture={() => { resize.current = undefined; }} />)}
    <header className="window-panel-header">
      <div><strong>{props.title}</strong>{props.subtitle && <small>{props.subtitle}</small>}</div>
      {props.actions}
      {!single && <><button type="button" aria-label={props.state.minimized ? 'Restore split view' : 'Minimize to focused pane'} onClick={() => props.onChange({ minimized: !props.state.minimized })}>{props.state.minimized ? 'Restore' : 'Minimize'}</button>
      <label>Layout <select aria-label="Window panel layout" value={props.state.mode}
        onChange={event => props.onChange({ mode: event.target.value as WindowPanelMode, minimized: false })}>
        {(props.modes ?? windowPanelModes).map(mode => <option key={mode} value={mode}>{windowPanelModeLabels[mode]}</option>)}
      </select></label></>}
      <button type="button" onClick={props.onClose} aria-label={`Close ${props.title}`}>Close</button>
    </header>
    {props.notice}
    <div className="window-panel-workspace">
      {!single && props.state.mode === 'split-single' && <div hidden={props.state.minimized} className="window-panel-canvas" aria-label="Canvas beside panel">{props.canvas}</div>}
      <div className="window-panel-content">
        {!single && !split && <div className="window-panel-tabs" role="tablist" aria-label="Panel panes">
          {props.panes.map(pane => <button key={pane.id} role="tab" id={`${tabId}-${pane.id}`} aria-controls={`${tabId}-${pane.id}-panel`}
            tabIndex={activePane === pane.id ? 0 : -1} aria-selected={activePane === pane.id}
            onKeyDown={event => {
              if (['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) {
                event.preventDefault(); const next = event.key === 'Home' ? props.panes[0] : event.key === 'End' ? props.panes[1]! : props.panes.find(p => p.id !== pane.id)!;
                props.onChange({ pane: next.id, focusedPane: next.id }); document.getElementById(`${tabId}-${next.id}`)?.focus();
              }
            }}
            onClick={() => props.onChange({ pane: pane.id, focusedPane: pane.id })}>{pane.title}</button>)}
        </div>}
        <div ref={body} className="window-panel-panes" style={{ '--tree-ratio': `${props.state.ratio * 100}%` } as CSSProperties}>
          {(split || activePane === props.panes[0].id) && <div className="window-panel-primary" data-pane={props.panes[0].id} data-focused={props.state.focusedPane === props.panes[0].id} {...paneEvents(props.panes[0].id)} role={single ? 'region' : split ? undefined : 'tabpanel'} id={`${tabId}-${props.panes[0].id}-panel`} aria-label={single ? props.panes[0].title : undefined} aria-labelledby={single || split ? undefined : `${tabId}-${props.panes[0].id}`}>{props.panes[0].content}</div>}
          {split && <div className="window-panel-divider" role="separator" aria-label={`Resize ${props.panes[0].title} and ${props.panes[1]!.title}`} aria-orientation="vertical" tabIndex={0}
            aria-valuemin={20} aria-valuemax={65} aria-valuenow={Math.round(props.state.ratio * 100)}
            onKeyDown={event => { if (['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) {
              event.preventDefault(); props.onChange({ ratio: event.key === 'Home' ? .2 : event.key === 'End' ? .65 : Math.max(.2, Math.min(.65, props.state.ratio + (event.key === 'ArrowLeft' ? -.03 : .03))) });
            } }}
            onPointerDown={event => { drag.current = true; event.currentTarget.focus(); event.currentTarget.setPointerCapture(event.pointerId); event.preventDefault(); }}
            onPointerMove={event => { if (drag.current && body.current) { const rect = body.current.getBoundingClientRect(); props.onChange({ ratio: Math.max(.2, Math.min(.65, (event.clientX - rect.left) / rect.width)) }); } }}
            onPointerUp={() => { drag.current = false; }} onPointerCancel={() => { drag.current = false; }} onLostPointerCapture={() => { drag.current = false; }} />}
          {!single && (split || activePane === props.panes[1]!.id) && <div className="window-panel-secondary" data-pane={props.panes[1]!.id} data-focused={props.state.focusedPane === props.panes[1]!.id} {...paneEvents(props.panes[1]!.id)} role={split ? undefined : 'tabpanel'} id={`${tabId}-${props.panes[1]!.id}-panel`} aria-labelledby={split ? undefined : `${tabId}-${props.panes[1]!.id}`}>{props.panes[1]!.content}</div>}
        </div>
      </div>
    </div>
  </section>;
}

